function onboarding(){return `<section class="onboarding"><p class="eyebrow">Персональная программа</p><h2>Сначала замерим твой максимум</h2><p class="onboarding-lead">Выполни по одному контрольному подходу в комфортных условиях. Введи максимальное количество качественных повторений и время планки. На их основе приложение построит программу на 4 недели с ориентиром примерно <strong>×1,5</strong>.</p><form id="baselineForm" class="baseline-form"><label><span>Имя</span><input name="name" type="text" maxlength="40" autocomplete="name" placeholder="Как тебя зовут?"><small>будет отображаться в профиле</small></label><label><span>Отжимания</span><input name="push" type="number" min="1" max="300" required placeholder="например, 18"><small>максимум повторений</small></label><label><span>Приседания</span><input name="squat" type="number" min="1" max="500" required placeholder="например, 60"><small>максимум повторений</small></label><label><span>Планка</span><div class="time-input"><input name="plankMin" type="number" min="0" max="20" value="0" required><b>мин</b><input name="plankSec" type="number" min="0" max="59" placeholder="40" required><b>сек</b></div><small>максимальное удержание</small></label><fieldset class="start-choice"><legend>Когда начать программу?</legend><label class="start-option"><input type="radio" name="startWhen" value="today" checked><span><b>Начать сегодня</b><small>Первая тренировка — сегодня</small></span></label><label class="start-option"><input type="radio" name="startWhen" value="tomorrow"><span><b>Начать завтра</b><small>Первая тренировка — завтра</small></span></label></fieldset><button class="check-btn" type="submit">Составить мой план</button></form></section>`}
function renderOnboarding(){document.querySelector('.main-nav').classList.add('hidden');document.querySelector('#todayView').classList.remove('hidden');document.querySelector('#planView').classList.add('hidden');document.querySelector('#profileView').classList.add('hidden');document.querySelector('#readingView').classList.add('hidden');document.querySelector('#todayWorkout').innerHTML=onboarding();document.querySelector('#baselineForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.currentTarget),name=String(f.get('name')||'').trim(),push=+f.get('push'),squat=+f.get('squat'),plank=+f.get('plankMin')*60+(+f.get('plankSec'));if(plank<10)return alert('Для планки укажи время не меньше 10 секунд.');let startWhen=String(f.get('startWhen')||'today'),startDate=addDays(isoLocal(),startWhen==='tomorrow'?1:0);state={profile:{name,push,squat,plank},startDate,done:{},notes:{},session:null,missed:{},readArticles:{},restSkips:0};save();hydratePlan();render()}}
function wordForm(n,one,few,many){n=Math.abs(Number(n)||0)%100;const n1=n%10;return n>10&&n<20?many:n1>1&&n1<5?few:n1===1?one:many}
function readableSpec(spec,type='reps'){if(!spec||spec==='—')return '—';const m=String(spec).match(/^(\d+)×(.+)$/);if(!m)return spec;const sets=+m[1],target=m[2].trim(),setWord=wordForm(sets,'подход','подхода','подходов');if(type==='time'){const sec=target.match(/^(\d+)\s*сек/);return sec?`${sets} ${setWord} × ${fmtTime(+sec[1])}`:`${sets} ${setWord} × ${target}`}const reps=target.match(/^(\d+)$/);return reps?`${sets} ${setWord} × ${reps[1]} ${wordForm(+reps[1],'повторение','повторения','повторений')}`:`${sets} ${setWord} × ${target}`}
function readableExtra(extra){const ex=extraParts(extra),timed=/\d+\s*сек/.test(ex.spec);return readableSpec(ex.spec,timed?'time':'reps')}
function card(w,big=false){const today=isoLocal(),inProgress=!!state.session&&Number(state.session.id)===Number(w.id),paused=inProgress&&!!state.session.paused,missed=!!state.missed?.[w.id]&&!state.done[w.id],future=w.date>today,canPlanComplete=!future&&!state.done[w.id]&&!inProgress,status=inProgress?`<span class="workout-status in-progress">${paused?'Тренировка на паузе':'Тренировка в процессе'}</span>`:state.done[w.id]?'<span class="workout-status completed">Выполнено</span>':missed?'<span class="workout-status missed">Пропущена</span>':future?'<span class="workout-status future">Запланирована</span>':'';return `<article class="workout ${big?'featured':''} ${state.done[w.id]?'done':''} ${inProgress?'is-progress':''} ${missed?'is-missed':''} ${future?'is-future':''}"><div class="workout-top"><div><p class="date">${fmt(w.date)} · Неделя ${w.week}</p><h3>${w.day}</h3>${status}</div>${!big&&canPlanComplete?`<button class="complete" data-id="${w.id}">Выполнить</button>`:''}</div><div class="exercise-grid"><div class="exercise"><span>Отжимания</span><strong>${readableSpec(w.push)}</strong></div><div class="exercise"><span>Приседания</span><strong>${readableSpec(w.squat)}</strong></div><div class="exercise"><span>Планка</span><strong>${readableSpec(w.plank,'time')}</strong></div><div class="exercise"><span>${extraParts(w.extra).name}</span><strong>${readableExtra(w.extra)}</strong></div></div>${big&&!state.done[w.id]&&!inProgress&&!missed&&!future?`<button class="start-workout" data-start="${w.id}">▶ Начать тренировку</button>`:''}${big&&state.done[w.id]?`<div class="workout-complete-label">✓ Тренировка выполнена</div>`:''}${!big&&inProgress?`<div class="plan-session-actions"><button class="continue-workout" data-continue="${w.id}">${paused?'▶ Продолжить тренировку':'Открыть тренировку'}</button><button class="finish-from-plan" data-finish-plan="${w.id}">✓ Выполнить тренировку</button></div>`:''}${!big&&missed?`<div class="missed-note">День тренировки уже прошёл. Её можно отметить выполненной вручную.</div>`:''}${!big&&future?`<div class="future-note">Эту тренировку можно выполнить только ${fmt(w.date)} или позже.</div>`:''}${!big&&!state.done[w.id]&&!inProgress&&Number(state.postponed?.[w.id])>0?`<button class="secondary restore-workout plan-restore" data-restore-postpone="${w.id}">Вернуть на день</button>`:''}</article>`}
function showCompletion(){const c=state.lastCompletion;if(!c)return;let mins=Math.floor(c.duration/60),secs=c.duration%60,pct=Math.round(c.programDone/c.programTotal*100),overlay=document.querySelector('#completionOverlay');if(!overlay){overlay=document.createElement('div');overlay.id='completionOverlay';overlay.className='completion-overlay';document.body.appendChild(overlay)}overlay.innerHTML=`<div class="completion-card"><div class="completion-mark">✓</div><p class="eyebrow">Тренировка завершена</p><h2>Отличная работа!</h2><p class="completion-sub">Ещё один день программы выполнен.</p><div class="completion-stats"><article><span>Время</span><strong>${String(mins).padStart(2,'0')}:${String(secs).padStart(2,'0')}</strong></article><article><span>Подходы</span><strong>${c.sets}</strong></article><article><span>Программа</span><strong>${pct}%</strong></article></div><div class="completion-progress"><i style="width:${pct}%"></i></div><small>${c.programDone} из ${c.programTotal} дней отмечено выполненными</small><button class="check-btn" id="closeCompletion">Готово</button></div>`;requestAnimationFrame(()=>overlay.classList.add('show'));document.querySelector('#closeCompletion').onclick=()=>{overlay.classList.remove('show');setTimeout(()=>overlay.remove(),220)}}
function estimatedWorkoutMinutes(w){if(!w)return 0;const steps=stepsFor(w),work=steps.reduce((sum,s)=>sum+(timedSeconds(s)||35),0),rests=Math.max(0,steps.length-1)*35;return Math.max(1,Math.round((work+rests)/60))}
function nextWorkoutText(w){const next=workouts.find(x=>Number(x.id)>Number(w.id));if(!next)return 'Программа завершена.';const diff=Math.round((new Date(next.date+'T12:00:00')-new Date(isoLocal()+'T12:00:00'))/86400000);return diff===1?'Следующая тренировка завтра.':diff===0?'Следующая тренировка сегодня.':`Следующая тренировка — ${fmt(next.date)}.`}
function todayContextHTML(w){if(!w)return '';const done=!!state.done[w.id],day=Math.max(1,Number(w.id)||1),weekday=dayName(w.date),today=isoLocal(),isToday=w.date===today,completed=workouts.filter(x=>state.done[x.id]).length,pct=Math.round(completed/workouts.length*100),dateLine=isToday?`Сегодня ~${estimatedWorkoutMinutes(w)} ${wordForm(estimatedWorkoutMinutes(w),'минута','минуты','минут')} работы.`:`Следующая тренировка — ${weekday}, ${fmt(w.date)} · ~${estimatedWorkoutMinutes(w)} ${wordForm(estimatedWorkoutMinutes(w),'минута','минуты','минут')}.`;if(done)return `<section class="today-context is-done"><div class="today-context-kicker">ТВОЯ ПРОГРАММА</div><h2>День ${day} закрыт <span aria-hidden="true">✓</span></h2><p>${nextWorkoutText(w)}</p></section>`;return `<section class="today-context"><div class="today-context-kicker">ТВОЯ ПРОГРАММА</div><h2>День ${day} <span>·</span> ${weekday}</h2><p>${dateLine}</p><p>Ты уже прошёл ${pct}% программы.</p></section>`}
function renderToday(){const playerHost=document.querySelector('#musicPlayerHost');if(playerHost&&!playerHost.firstElementChild)playerHost.innerHTML=musicHTML();const today=isoLocal(),first=workouts[0],last=workouts.at(-1),sessionWorkout=state.session?workouts.find(x=>Number(x.id)===Number(state.session.id)):null;let w=sessionWorkout||workouts.find(x=>x.date===today),msg='';if(sessionWorkout){msg=state.session.paused?'Тренировка сохранена на паузе. Продолжи с того же места.':'Тренировка уже начата.'}else if(today<first.date){w=first;msg=`План стартует ${fmt(first.date)}.`}else if(today>last.date){w=last;msg='Четырёхнедельный план завершён. Ниже — итоговый тест.'}else if(!w){w=workouts.find(x=>x.date>today)||last;msg=`Ближайшая тренировка — ${fmt(w.date)}.`}else msg=state.done[w.id]?'Сегодняшняя тренировка уже отмечена.':'Персональная тренировка на сегодня готова.';const contextHost=document.querySelector('#todayContextHost');if(contextHost)contextHost.innerHTML=todayContextHTML(w);document.querySelector('#todayWorkout').innerHTML=sessionWorkout?sessionHTML(sessionWorkout):`${card(w,true)}${!state.done[w.id]&&!state.session&&w.date>=today?`<div class="postpone-actions"><button class="secondary postpone-workout postpone-below" data-postpone="${w.id}">Отложить тренировку</button>${Number(state.postponed?.[w.id])>0?`<button class="secondary restore-workout postpone-below" data-restore-postpone="${w.id}">Вернуть на день</button>`:''}</div>`:''}`}
function completedWorkouts(){return workouts.filter(w=>state.done[w.id]).length}
function plankTotal(spec){const m=String(spec||'').match(/^(\d+)×(\d+)\s*сек/);return m?Number(m[1])*Number(m[2]):0}
function userStats(){let push=0,squat=0,plank=0;for(const w of workouts){if(!state.done[w.id])continue;push+=specTotal(w.push);squat+=specTotal(w.squat);plank+=plankTotal(w.plank)}return {workouts:completedWorkouts(),push,squat,plank}}
function profileStage(done){if(done>=28)return 'Программа завершена';if(done>=21)return 'Финишная неделя';if(done>=14)return 'Половина пути пройдена';if(done>=7)return 'Первая неделя закрыта';if(done>0)return 'Хорошее начало';return 'Всё впереди'}
function renderProfile(){const el=document.querySelector('#profileView');if(!el||!state.profile)return;const b=state.profile,s=userStats(),t={push:Math.round(b.push*1.5),squat:Math.round(b.squat*1.5),plank:Math.round(b.plank*1.5)},name=String(b.name||'').trim(),total=workouts.length||28,done=s.workouts,pct=Math.min(100,Math.round(done/total*100)),today=isoLocal(),current=workouts.find(w=>w.date===today)||workouts.find(w=>w.date>today)||workouts.at(-1),day=current?Math.max(1,Number(current.id)||1):1,plankLabel=fmtTime(s.plank);el.innerHTML=`<section class="profile-page profile-dashboard"><div class="profile-heading profile-dashboard-head"><div><h2>${name||'Твой профиль'}</h2></div>${name?'':`<button class="secondary" id="setProfileName">Добавить имя</button>`}</div><section class="profile-section profile-metrics"><h3 class="profile-section-title">Твои показатели</h3><div class="profile-stats profile-stat-grid"><article><span>Тренировок завершено</span><strong>${s.workouts}</strong></article><article><span>Отжиманий</span><strong>${s.push}</strong></article><article><span>Приседаний</span><strong>${s.squat}</strong></article><article><span>Планка</span><strong>${plankLabel}</strong></article></div></section><section class="profile-progress-card"><div class="profile-ring" style="--profile-pct:${pct}"><div class="profile-ring-core"><strong>${pct}%</strong><span>${done} / ${total}</span></div></div><div class="profile-progress-copy"><p class="eyebrow">Программа</p><h3>${profileStage(done)}</h3><p>Пройдено ${done} из ${total} тренировок.</p></div></section><section class="profile-section profile-targets"><h3 class="profile-section-title">Твоя цель</h3><div class="goal-grid"><article class="goal-card"><span>Отжимания</span><strong>${t.push}</strong></article><article class="goal-card"><span>Приседания</span><strong>${t.squat}</strong></article><article class="goal-card"><span>Планка</span><strong>${fmtTime(t.plank)}</strong></article></div></section><div class="profile-achievements"><h3 class="profile-section-title">Достижения</h3><div id="achievementsGrid" class="achievements-grid"></div></div></section>`;renderAchievements();const btn=document.querySelector('#setProfileName');if(btn)btn.onclick=()=>{const v=prompt('Как тебя зовут?',state.profile.name||'');if(v!==null){state.profile.name=String(v).trim().slice(0,40);save();renderProfile()}}}

// v96 — match-3 mini game
const M3={rows:7,cols:7,types:['🏋️','💪','⚡','🔥','🥤','👟'],board:[],selected:null,score:state.match3Score,busy:false};
function m3Index(r,c){return r*M3.cols+c}
function m3RC(i){return [Math.floor(i/M3.cols),i%M3.cols]}
function m3Adjacent(a,b){const [ar,ac]=m3RC(a),[br,bc]=m3RC(b);return Math.abs(ar-br)+Math.abs(ac-bc)===1}
function m3Matches(){const hit=new Set();for(let r=0;r<M3.rows;r++){let start=0;for(let c=1;c<=M3.cols;c++){if(c<M3.cols&&M3.board[m3Index(r,c)]===M3.board[m3Index(r,start)])continue;if(c-start>=3)for(let x=start;x<c;x++)hit.add(m3Index(r,x));start=c}}for(let c=0;c<M3.cols;c++){let start=0;for(let r=1;r<=M3.rows;r++){if(r<M3.rows&&M3.board[m3Index(r,c)]===M3.board[m3Index(start,c)])continue;if(r-start>=3)for(let y=start;y<r;y++)hit.add(m3Index(y,c));start=r}}return [...hit]}
function m3Swap(a,b){[M3.board[a],M3.board[b]]=[M3.board[b],M3.board[a]]}
function m3HasMove(){for(let i=0;i<M3.board.length;i++){const [r,c]=m3RC(i);for(const j of [c+1<M3.cols?i+1:-1,r+1<M3.rows?i+M3.cols:-1])if(j>=0){m3Swap(i,j);const ok=m3Matches().length>0;m3Swap(i,j);if(ok)return true}}return false}
function m3FillFresh(){do{M3.board=[];for(let i=0;i<M3.rows*M3.cols;i++){let choices=M3.types.filter(t=>{const [r,c]=m3RC(i);return !(c>=2&&M3.board[i-1]===t&&M3.board[i-2]===t)&&!(r>=2&&M3.board[i-M3.cols]===t&&M3.board[i-2*M3.cols]===t)});M3.board.push(choices[Math.floor(Math.random()*choices.length)])}}while(!m3HasMove())}
function m3Collapse(){const moves=[];for(let c=0;c<M3.cols;c++){const kept=[];for(let r=M3.rows-1;r>=0;r--){const i=m3Index(r,c),v=M3.board[i];if(v)kept.push({v,from:r})}for(let r=M3.rows-1,k=0;r>=0;r--,k++){const i=m3Index(r,c);if(k<kept.length){M3.board[i]=kept[k].v;moves.push({i,rows:r-kept[k].from})}else{M3.board[i]=M3.types[Math.floor(Math.random()*M3.types.length)];moves.push({i,rows:r+1})}}}return moves}
function m3Explode(matched){return new Promise(resolve=>{const board=document.querySelector('#match3Board');if(!board){resolve();return}matched.forEach(i=>{const cell=board.querySelector('[data-m3="'+i+'"]');if(cell){cell.classList.add('exploding');for(let p=0;p<5;p++){const spark=document.createElement('i');spark.className='m3-spark';spark.style.setProperty('--a',(p*72+Math.random()*24)+'deg');cell.appendChild(spark)}}});setTimeout(resolve,300)})}
function m3DropRender(moves){m3Render();const board=document.querySelector('#match3Board');if(!board)return;const step=(board.clientWidth-(M3.cols-1)*5)/M3.cols+5;(moves||[]).forEach(({i,rows})=>{if(rows<=0)return;const cell=board.querySelector('[data-m3="'+i+'"]');if(cell){cell.style.setProperty('--fall-from',(-rows*step)+'px');cell.style.setProperty('--drop-delay',(m3RC(i)[0]*12)+'ms');cell.classList.add('dropping')}})}
async function m3Resolve(){let loops=0,matched;while((matched=m3Matches()).length&&loops++<30){M3.score+=matched.length*10;state.match3Score=M3.score;save();const score=document.querySelector('#match3Score');if(score)score.textContent=M3.score;await m3Explode(matched);matched.forEach(i=>M3.board[i]=null);const moves=m3Collapse();m3DropRender(moves);await new Promise(r=>setTimeout(r,380))}if(!m3HasMove()){m3FillFresh();m3Render()}M3.busy=false;m3Render()}
function m3Render(){const board=document.querySelector('#match3Board'),score=document.querySelector('#match3Score');if(!board)return;if(score)score.textContent=M3.score;board.innerHTML=M3.board.map((v,i)=>'<button type="button" class="m3-cell '+(M3.selected===i?'selected':'')+'" data-m3="'+i+'" aria-label="Фишка '+v+'">'+v+'</button>').join('');board.querySelectorAll('[data-m3]').forEach(b=>b.onclick=()=>m3Pick(Number(b.dataset.m3)))}
function m3Pick(i){if(M3.busy)return;if(M3.selected===null){M3.selected=i;m3Render();return}if(M3.selected===i){M3.selected=null;m3Render();return}if(!m3Adjacent(M3.selected,i)){M3.selected=i;m3Render();return}const a=M3.selected;M3.selected=null;m3Swap(a,i);if(!m3Matches().length){m3Swap(a,i);m3Render();return}M3.busy=true;m3Render();setTimeout(()=>m3Resolve(),120)}
function m3Mount(){const board=document.querySelector('#match3Board');if(!board)return;if(!M3.board.length)m3FillFresh();m3Render();const reset=document.querySelector('#match3Reset');if(reset)reset.onclick=()=>{M3.selected=null;m3FillFresh();m3Render()}}

function renderReading(){const el=document.querySelector('#readingView');if(!el)return;state.readArticles=state.readArticles||{};const articles=[["01","Вода утром: полезная привычка, но не суперсила","Привычки","После сна нормально хотеть пить: несколько часов организм не получал жидкость. Стакан воды утром — простой способ начать восполнять её, особенно перед тренировкой.","Важнее общая гидратация в течение дня. Потребность зависит от активности, жары, питания и других факторов.","Перед тренировкой: если хочется пить — выпей воды. Большой объём залпом не нужен."],["02","5 известных спортсменов","Истории","Майкл Фелпс, Серена Уильямс, Усэйн Болт, Симона Байлз и Криштиану Роналду выступали в разных видах спорта, но их карьеры хорошо показывают ценность многолетней системной работы.","За яркими соревнованиями обычно стоят тысячи повторений, восстановление и корректировки программы.","Сравнивай сегодняшний результат прежде всего со своим прошлым результатом."],["03","Чем полезны отжимания?","Упражнения","Отжимания одновременно нагружают грудные мышцы, трицепсы и переднюю часть плеч. Корпус тоже работает, удерживая тело стабильным.","Нагрузка легко масштабируется: от высокой опоры до классического варианта и более сложных прогрессий.","Лучше меньше повторений с одинаковой техникой, чем больше с сокращённой амплитудой."],["04","Не тренируйся до отказа каждый раз","Лайфхак","Каждый подход необязательно заканчивать полной невозможностью сделать ещё одно повторение. Постоянная работа до отказа добавляет утомление.","В обычной тренировке удобно сохранять небольшой запас, а максимум проверять в специально отведённые дни.","Техника заметно разваливается — подход пора заканчивать."],["05","Как не слить утреннюю тренировку","Лайфхак","Чем меньше решений нужно принять утром, тем проще начать. Подготовь одежду и место вечером, а утром договорись с собой только о первом упражнении.","Так старт требует меньше усилий и не превращается в долгие переговоры с собой.","Задача первых двух минут — просто начать двигаться."],["06","Отдых между подходами — это часть тренировки","Лайфхак","Пауза помогает следующему подходу снова получиться качественным. Слишком короткий отдых может уменьшить число хороших повторений.","Ориентируйся на таймер, дыхание и качество техники.","Восстанови дыхание и держи внимание на следующем упражнении, а не на ленте телефона."],["07","Чем полезны приседания?","Упражнения","Приседания тренируют прежде всего мышцы ног и ягодиц, а корпус помогает стабилизировать положение тела.","Для прогресса важнее контролируемая амплитуда и устойчивое положение стоп, чем погоня за скоростью.","Колени движутся в направлении носков, а стопа остаётся уверенно на полу."],["08","Зачем нужна планка?","Упражнения","Планка развивает способность корпуса сохранять стабильное положение. Работают мышцы живота, плечевого пояса и ягодиц.","Длиннее — не всегда лучше. Качественное удержание полезнее долгого подхода с потерей положения.","Слегка подкрути таз и напряги ягодицы — корпус станет собраннее."],["09","Выпады: сила по одной ноге","Упражнения","Выпады дают каждой ноге отдельную работу и дополнительно требуют равновесия. Это помогает заметить разницу между сторонами.","Начинай с удобной длины шага и спокойного темпа. Для баланса можно слегка придерживаться за устойчивую опору.","Сначала уверенное движение, потом дополнительные повторения."],["10","Зачем нужен ягодичный мостик?","Упражнения","Ягодичный мостик — простой способ нагрузить ягодичные мышцы без сложного оборудования. Он хорошо дополняет приседания и выпады.","В верхней точке не нужно чрезмерно прогибать поясницу: движение заканчивается, когда таз поднят, а ягодицы напряжены.","Сделай короткую паузу в верхней точке вместо быстрых повторений."],["11","Сила привычки: почему помогает одно время","Привычки","Повторяющийся контекст снижает количество решений: одно время, место и последовательность постепенно становятся сигналом к тренировке.","Необязательно попадать в минуту. Важнее создать узнаваемый сценарий.","Привяжи тренировку к уже существующей утренней привычке."],["12","Сон — часть тренировочного плана","Привычки","Тренировка создаёт нагрузку, а восстановление происходит между тренировками. Недостаток сна может ухудшать самочувствие и качество упражнений.","Регулярный режим сна обычно практичнее попыток отоспаться когда-нибудь потом.","Подготовь всё для тренировки заранее и убери одну причину откладывать сон."],["13","Почему полезно отмечать тренировки","Привычки","Запись выполненных тренировок превращает абстрактное «вроде занимаюсь» в понятную историю прогресса.","Так проще оценивать тенденцию за недели, а не настроение после одного удачного или неудачного дня.","Даты и факта выполнения уже достаточно, чтобы видеть регулярность."],["14","Разминка без лишней сложности","Лайфхак","Перед короткой домашней тренировкой разминка тоже может быть короткой. Несколько минут лёгких движений постепенно готовят к нагрузке.","Используй движения, похожие на предстоящие упражнения: плечи, лёгкие приседания и простые повторения.","Начни легко и постепенно приблизься к рабочему движению."],["15","Что делать, если сегодня мало сил","Лайфхак","Самочувствие меняется изо дня в день. Если обычная нагрузка ощущается значительно тяжелее, тренировку не обязательно превращать в проверку характера.","Можно снизить темп, увеличить паузы и особенно внимательно следить за техникой.","Сохраняй регулярность без необходимости каждый день ставить рекорд."],["16","Не усложняй прогрессию слишком рано","Лайфхак","Прогресс хорошо строится и на базовом движении: больше качественных повторений, лучше контроль и стабильнее техника.","Усложнение имеет смысл, когда текущий вариант выполняется уверенно.","Сначала контроль, потом объём, затем более сложная версия."],["17","Майкл Фелпс: ценность повторяемости","Истории","Плавание требует огромного количества технически похожих повторений. Карьера Майкла Фелпса хорошо иллюстрирует ценность системной подготовки.","Для любителя масштаб другой, но принцип узнаваем: одна тренировка мало что решает, серия тренировок — уже многое.","Не ищи магическую тренировку — собирай последовательность."],["18","Усэйн Болт: скорость строится не только скоростью","Истории","Спринтерский результат зависит не только от способности быстро бежать. В подготовке важны техника, силовая работа и восстановление.","Конечный навык часто состоит из нескольких качеств, которые развиваются вместе.","Сила, контроль и регулярность дополняют друг друга."],["19","Симона Байлз: сложность начинается с базы","Истории","Элитная гимнастика выглядит невероятно сложной, но сложные элементы опираются на силу, координацию, технику и базовую работу.","Тот же принцип полезен новичку: устойчивые базовые движения дают платформу для будущего усложнения.","Уверенная база — не скучный этап, а часть результата."],["20","Серена Уильямс: длинная дистанция","Истории","Карьера Серены Уильямс охватила много лет выступлений на высшем уровне. Спортивная форма меняется не за один день.","В четырёхнедельном плане полезно смотреть не на один подход, а на направление движения от недели к неделе.","Оценивай прогресс сериями тренировок, а не одним утром."]];const sorted=[...articles].sort((a,b)=>Number(!!state.readArticles[a[0]])-Number(!!state.readArticles[b[0]])||Number(a[0])-Number(b[0]));const readCount=articles.filter(a=>state.readArticles[a[0]]).length;el.innerHTML='<section class="reading-page"><h2>Коротко о полезном</h2><p class="reading-lead">20 коротких статей про упражнения, спортивные привычки, лайфхаки и истории спортсменов. Прочитанные материалы становятся серыми и уходят вниз.</p><div class="reading-counter">'+readCount+' из 20 прочитано</div><div class="reading-list">'+sorted.map(a=>{const num=a[0],title=a[1],tag=a[2],p1=a[3],p2=a[4],tip=a[5],read=!!state.readArticles[num];return '<details class="reading-card reading-fold '+(read?'is-read':'')+'" data-article="'+num+'"><summary><span class="reading-num">'+num+'</span><span class="reading-summary"><small>'+tag+'</small><strong>'+title+'</strong></span><span class="reading-chevron" aria-hidden="true">⌄</span></summary><div class="reading-body"><p>'+p1+'</p><p>'+p2+'</p><div class="reading-tip"><b>Коротко:</b> '+tip+'</div></div></details>'}).join('')+'</div><section class="match3-game"><div class="match3-head"><div><small>МИНИ-ИГРА</small><h3>Три в ряд</h3></div><div class="match3-score">Счёт <strong id="match3Score">0</strong></div></div><p class="match3-help">Меняй соседние фишки местами и собирай 3 или больше одинаковых в ряд.</p><div id="match3Board" class="match3-board" aria-label="Игра три в ряд"></div><button id="match3Reset" class="secondary match3-reset" type="button">Новая игра</button></section></section>';m3Mount();let activeArticle=null,autoClosing=false;document.querySelectorAll('#readingView [data-article]').forEach(d=>d.addEventListener('toggle',()=>{if(d.open){const previous=activeArticle;if(previous&&previous!==d&&!state.readArticles[previous.dataset.article])state.readArticles[previous.dataset.article]=true;autoClosing=true;document.querySelectorAll('#readingView [data-article]').forEach(other=>{if(other!==d&&other.open)other.open=false});autoClosing=false;activeArticle=d;if(previous&&previous!==d){save();renderReading();const current=document.querySelector('#readingView [data-article="'+d.dataset.article+'"]');if(current)current.open=true}return}if(autoClosing)return;if(activeArticle===d){activeArticle=null;if(!state.readArticles[d.dataset.article]){state.readArticles[d.dataset.article]=true;save();renderReading()}}}))}

function markPlanWorkoutDone(id){const w=workouts.find(x=>Number(x.id)===Number(id));if(!w||state.done[w.id])return;if(w.date>isoLocal()){alert('Тренировку из будущего нельзя отметить выполненной.');return}const label=w.date<isoLocal()?'пропущенную тренировку':'сегодняшнюю тренировку';if(!confirm(`Отметить ${label} как выполненную?`))return;state.done[w.id]=true;if(state.missed?.[w.id])delete state.missed[w.id];save();render()}
function bindPlanWeeks(){document.querySelectorAll('[data-plan-week]').forEach(btn=>btn.onclick=()=>{planWeek=Number(btn.dataset.planWeek);renderPlan();bind()})}
function bind(){bindPlanWeeks();document.querySelectorAll('.complete').forEach(b=>b.onclick=()=>markPlanWorkoutDone(+b.dataset.id));document.querySelectorAll('.notes').forEach(n=>n.oninput=()=>{state.notes[n.dataset.note]=n.value;save()});document.querySelectorAll('[data-start]').forEach(e=>e.onclick=()=>startSession(+e.dataset.start));document.querySelectorAll('[data-postpone]').forEach(e=>e.onclick=()=>postponeWorkout(+e.dataset.postpone));document.querySelectorAll('[data-restore-postpone]').forEach(e=>e.onclick=()=>restorePostponedWorkout(+e.dataset.restorePostpone));document.querySelectorAll('[data-continue]').forEach(e=>e.onclick=()=>{currentView='today';render()});document.querySelectorAll('[data-finish-plan]').forEach(e=>e.onclick=()=>finishSessionFromPlan(+e.dataset.finishPlan));document.querySelectorAll('[data-session-action]').forEach(e=>e.onclick=sessionAction);bindMusic();document.querySelectorAll('.main-tab').forEach(b=>b.onclick=()=>{currentView=b.dataset.view;render()})}
function render(){
 if(!state.profile){renderOnboarding();syncWelcome();return}
 hydratePlan(); syncMissedWorkouts();
 document.querySelector('.main-nav').classList.remove('hidden');
 ['today','plan','reading','profile'].forEach(v=>document.querySelector('#'+v+'View')?.classList.toggle('hidden',currentView!==v));
 document.querySelectorAll('.main-tab').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));
 renderToday(); renderProfile(); renderPlan(); renderReading(); bind(); syncWelcome();
}
function currentPlanWeek(){
 if(!workouts.length)return 1;
 const today=isoLocal(),first=workouts[0].date,last=workouts[workouts.length-1].date;
 if(today<first)return 1;
 if(today>last)return 4;
 const found=workouts.find(w=>w.date===today);
 if(found)return found.week;
 const elapsed=Math.floor((new Date(today+'T12:00:00')-new Date(first+'T12:00:00'))/86400000);
 return Math.max(1,Math.min(4,Math.floor(elapsed/7)+1));
}
function renderPlan(){
 const activeWeek=currentPlanWeek();
 if(!planWeek||planWeek<1||planWeek>4)planWeek=activeWeek;
 const summary=document.querySelector('#weekSummary');
 if(summary) summary.innerHTML=`<p class="plan-intro">Здесь ты можешь ознакомиться с планом тренировок на 4 недели.</p>`;
 const tabs=document.querySelector('#weekTabs');
 if(tabs)tabs.innerHTML=[1,2,3,4].map(week=>`<button type="button" class="week-tab ${planWeek===week?'active':''}" data-plan-week="${week}"><span>${week} неделя</span>${week===activeWeek?'<small>Текущая</small>':''}</button>`).join('');
 document.querySelector('#workouts').innerHTML=workouts.filter(w=>w.week===planWeek).map(w=>card(w)).join('');
 bindPlanWeeks();
}
function specTotal(spec){
 const m=String(spec||'').match(/^(\d+)×(\d+)(?:\s|$)/); return m?Number(m[1])*Number(m[2]):0;
}
function achievementProgress(){
 let push=0,squat=0;
 for(const w of workouts){if(state.done[w.id]){push+=specTotal(w.push);squat+=specTotal(w.squat)}}
 const done=completedWorkouts(),readCount=Object.values(state.readArticles||{}).filter(Boolean).length,listened=state.listenedTracks||{};return {measure:state.profile?1:0,steady:done>0?1:0,squats500:Math.min(500,squat),pushups100:Math.min(100,push),fox:Math.min(30,Number(state.restSkips)||0),reader:Math.min(20,readCount),mewskul:listened['Мяускулы кота']?1:0,lakeSquat:listened['Присед у озера']?1:0,microkachok:listened['Микрокачок']?1:0,bratstvo:listened['Братство качков']?1:0,cowboy:listened['Качок-ковбой']?1:0,fishGym:listened['Рыбная качалка']?1:0,dinosaur:listened['Кач, динозавр!']?1:0,week1:Math.min(7,done),week2:Math.min(14,done),week3:Math.min(21,done),week4:Math.min(28,done)};
}
