function renderAchievements(){
 const grid=document.querySelector('#achievementsGrid'); if(!grid||!state.profile)return;
 const p=achievementProgress();
 grid.innerHTML=ACHIEVEMENTS.map(a=>{const value=p[a.id],pct=Math.min(100,Math.round(value/a.goal*100)),ok=value>=a.goal;return `<article class="achievement-card ${ok?'unlocked':'locked'}"><div class="achievement-art"><img src="${a.img}" alt="${a.title}">${ok?'':'<span class="achievement-state">🔒</span>'}</div><div class="achievement-copy"><h3>${a.title}</h3><p>${a.desc}</p><div class="achievement-progress"><div style="width:${pct}%"></div></div><div class="achievement-numbers"><b>${value} / ${a.goal}</b><span>${pct}%</span></div></div></article>`}).join('');
}
function syncWelcome(){
 const w=document.querySelector('#welcomeV12'); if(!w)return;
 const shouldShow=!state.profile && !sessionStorage.getItem('welcomeDismissed');
 w.classList.toggle('hidden',!shouldShow); document.body.classList.toggle('onboarding-open',shouldShow);
}
const settingsModal=document.querySelector('#settingsModal'),gifToggle=document.querySelector('#gifToggle');function syncGifSetting(){if(!gifToggle)return;gifToggle.setAttribute('aria-checked',state.musicGifEnabled?'true':'false');gifToggle.setAttribute('aria-label',state.musicGifEnabled?'Выключить GIF в плеере':'Включить GIF в плеере')}function setSettingsOpen(open){if(!settingsModal)return;settingsModal.classList.toggle('hidden',!open);document.body.classList.toggle('settings-open',open);if(open)syncGifSetting()}gifToggle.onclick=()=>{state.musicGifEnabled=!state.musicGifEnabled;save();syncGifSetting();const host=document.querySelector('#musicPlayerHost');if(host){host.innerHTML=musicHTML();bindMusic();updateMusicUI()}};document.querySelector('#settingsBtn').onclick=()=>setSettingsOpen(true);document.querySelector('#settingsClose').onclick=()=>setSettingsOpen(false);settingsModal.onclick=e=>{if(e.target===settingsModal)setSettingsOpen(false)};document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!settingsModal.classList.contains('hidden'))setSettingsOpen(false)});document.querySelector('#resetBtn').onclick=()=>{if(confirm('Сбросить персональную программу, результаты и пройти стартовый тест заново?')){setSettingsOpen(false);localStorage.removeItem(KEY);sessionStorage.removeItem('welcomeDismissed');state={done:{},notes:{},session:null,missed:{},postponed:{},readArticles:{},listenedTracks:{},restSkips:0,match3Score:0,musicGifEnabled:false};workouts=[];currentView='today';render()}};
function parseSpec(name,spec){if(!spec||spec==='—')return[];let m=spec.match(/(\d+)×(.+)/);if(!m)return[{name,target:spec,set:1,sets:1,rest:60}];let n=+m[1],target=m[2].trim();return Array.from({length:n},(_,i)=>({name,target,set:i+1,sets:n,rest:60}))}
function extraParts(extra){const m=String(extra||'').match(/^(.+?)\s+(\d+)×(.+)$/);if(!m)return{name:extra,spec:extra};let name=m[1].trim(),sets=+m[2],target=m[3].trim();if(/\/нога$/.test(target)){name+=' · на каждую ногу';target=target.replace('/нога','')}else if(/\/сторона$/.test(target)){name+=' · на каждую сторону';target=target.replace('/сторона','')}return{name,spec:`${sets}×${target.trim()}`}}
function stepsFor(w){const ex=extraParts(w.extra);let extraSteps=parseSpec(ex.name,ex.spec);if(/на каждую сторону/.test(ex.name)&&extraSteps.some(s=>timedSeconds(s)>0)){extraSteps=extraSteps.flatMap(s=>[{...s,side:1,sides:2},{...s,side:2,sides:2}])}const groups=[parseSpec('Отжимания',w.push),parseSpec('Приседания',w.squat),parseSpec('Планка',w.plank),extraSteps].filter(g=>g.length),steps=[],max=Math.max(0,...groups.map(g=>g.length));for(let round=0;round<max;round++)groups.forEach(g=>{if(g[round])steps.push({...g[round],round:round+1,rest:35})});return steps.map((s,i)=>({...s,next:i<steps.length-1?steps[i+1].name:null}))}
function finishSessionFromPlan(id){const s=state.session;if(!s||Number(s.id)!==Number(id))return;const w=workouts.find(x=>Number(x.id)===Number(id));if(!w)return;if(w.date>isoLocal()){alert('Тренировку из будущего нельзя отметить выполненной.');return}if(!confirm('Отметить начатую тренировку как полностью выполненную? Незавершённые подходы будут считаться выполненными.'))return;clearSessionTimer();const steps=stepsFor(w),doneCountBefore=Object.values(state.done||{}).filter(Boolean).length;state.done[w.id]=true;if(state.missed?.[w.id])delete state.missed[w.id];state.lastCompletion={id:w.id,duration:Math.max(1,Math.round((Date.now()-(s.startedAt||Date.now()))/1000)),sets:steps.length,total:steps.length,programDone:doneCountBefore+(state.done[w.id]?1:0),programTotal:workouts.length,at:Date.now()};state.session=null;save();render();showCompletion()}
function startSession(id){clearSessionTimer();if(state.session&&Number(state.session.id)!==Number(id)){currentView='today';render();return}const first=stepsFor(workouts.find(x=>Number(x.id)===Number(id)))[0];state.session={id,index:0,phase:timedSeconds(first)?'prepare':'set',remaining:timedSeconds(first)?3:0,startedAt:Date.now(),completedSets:0,paused:false,pausedAt:null};ensureWorkoutMusic(workouts.find(x=>Number(x.id)===Number(id)),true);save();render()}
function timedSeconds(step){if(!step)return 0;const m=String(step.target||'').match(/(\d+)(?:[–-](\d+))?\s*сек/);return m?Number(m[2]||m[1]):0}
function sessionHTML(w){let s=state.session,steps=stepsFor(w);if(!steps.length)return card(w,true);let st=steps[Math.min(s.index,steps.length-1)],pct=Math.round(s.index/steps.length*100),timed=timedSeconds(st)>0,cleanTarget=String(st.target||'').replace(/\s*·.*$/,''),sideText=st.sides?` · Сторона ${st.side} из ${st.sides}`:'';if(s.paused){clearSessionTimer();return `<section class="session paused-session"><div class="session-head"><span>Тренировка на паузе</span><strong>${pct}%</strong></div><div class="session-progress"><div style="width:${pct}%"></div></div><div class="active-step"><div class="exercise-label">ПРОДОЛЖИШЬ С ЭТОГО МЕСТА</div><h2>${st.name}</h2><div class="set-counter">Подход <strong>${st.set||1}</strong> из <strong>${st.sets||1}</strong>${sideText}</div><div class="work-target"><span>${timed?'Время':'Повторения'}</span><strong>${timed?fmtTime(timedSeconds(st)):cleanTarget}</strong></div><button class="check-btn" data-session-action="resume">▶ Продолжить тренировку</button><div class="resume-note">Прогресс сохранён</div></div></section>`}const countdown=['rest','prepare','exercise'].includes(s.phase);if(countdown)scheduleSessionTick();else clearSessionTimer();const total=s.phase==='prepare'?3:s.phase==='exercise'?timedSeconds(st):35,timerPct=countdown?Math.max(0,Math.min(1,s.remaining/Math.max(1,total))):1,circ=289,label=s.phase==='prepare'?'Приготовься':s.phase==='exercise'?'Выполняй подход':'Отдых между упражнениями';return `<section class="session"><div class="session-head"><span>Упражнение ${Math.min(s.index+1,steps.length)} из ${steps.length}</span><strong>${pct}%</strong></div><div class="session-progress"><div style="width:${pct}%"></div></div>${countdown?`<div class="rest ${s.phase}"><p class="rest-label">${label}</p><div class="timer-ring"><svg viewBox="0 0 104 104"><circle class="ring-bg" cx="52" cy="52" r="46"/><circle class="ring-fg" cx="52" cy="52" r="46" style="stroke-dasharray:${circ};stroke-dashoffset:${circ*(1-timerPct)}"/></svg><div class="timer-small">${fmtTime(s.remaining)}</div></div>${s.phase==='rest'?`<div class="up-next"><span>Следующее упражнение</span><strong>${st.name}</strong><small>Подход ${st.set||1} из ${st.sets||1}${sideText} · ${timed?`время ${fmtTime(timedSeconds(st))}`:`${cleanTarget} повторений`}</small></div>`:`<div class="timed-caption">${s.phase==='prepare'?`Подход ${st.set||1} из ${st.sets||1}${sideText} · старт через 3 секунды`:`Подход ${st.set||1} из ${st.sets||1}${sideText}`}</div>`}<button class="secondary wide" data-session-action="skip">${s.phase==='prepare'?'Начать сейчас':s.phase==='exercise'?'Завершить подход':'Пропустить отдых'}</button></div>`:`<div class="active-step"><div class="exercise-label">ТЕКУЩЕЕ УПРАЖНЕНИЕ</div><h2>${st.name}</h2><div class="set-counter">Подход <strong>${st.set||1}</strong> из <strong>${st.sets||1}</strong>${sideText}</div><div class="work-target"><span>${timed?'Время':'Повторения'}</span><strong>${timed?fmtTime(timedSeconds(st)):cleanTarget}</strong></div><button class="check-btn" data-session-action="done">✓ Подход выполнен</button>${st.next?`<div class="next-simple">Дальше: <strong>${st.next}</strong></div>`:''}</div>`}<div class="session-actions"><button class="secondary" data-session-action="exit">Завершить позже</button></div></section>`}
function advanceSession(w,steps){clearSessionTimer();let s=state.session;s.completedSets=(s.completedSets||0)+1;s.index++;if(s.index>=steps.length){state.done[w.id]=true;const doneCount=Object.values(state.done||{}).filter(Boolean).length;state.lastCompletion={id:w.id,duration:Math.max(1,Math.round((Date.now()-(s.startedAt||Date.now()))/1000)),sets:s.completedSets,total:steps.length,programDone:doneCount,programTotal:workouts.length,at:Date.now()};state.session=null;save();render();showCompletion();return true}s.phase='rest';s.remaining=35;return false}
function sessionAction(e){clearSessionTimer();let a=e.currentTarget.dataset.sessionAction,s=state.session;if(!s)return;let w=workouts.find(x=>x.id===s.id),steps=stepsFor(w),st=steps[Math.min(s.index,steps.length-1)];if(a==='done'&&advanceSession(w,steps))return;if(a==='skip'){if(s.phase==='prepare'){s.phase='exercise';s.remaining=timedSeconds(st)}else if(s.phase==='exercise'){if(advanceSession(w,steps))return}else{state.restSkips=(Number(state.restSkips)||0)+1;if(timedSeconds(st)){s.phase='prepare';s.remaining=3}else{s.phase='set';s.remaining=0}}}if(a==='exit'){s.paused=true;s.pausedAt=Date.now();save();render();return}if(a==='resume'){if(s.pausedAt&&s.startedAt)s.startedAt+=Math.max(0,Date.now()-s.pausedAt);s.paused=false;s.pausedAt=null;save();render();return}save();render()}
function tickRest(){clearSessionTimer();let s=state.session;if(!s||!['rest','prepare','exercise'].includes(s.phase))return;if(s.remaining>0){s.remaining--;save();render();return}let w=workouts.find(x=>x.id===s.id),steps=stepsFor(w),st=steps[Math.min(s.index,steps.length-1)];if(s.phase==='prepare'){s.phase='exercise';s.remaining=timedSeconds(st)}else if(s.phase==='exercise'){if(advanceSession(w,steps))return}else if(timedSeconds(st)){s.phase='prepare';s.remaining=3}else s.phase='set';save();render()}
render();



document.addEventListener('click',e=>{if(e.target?.id==='welcomeStart'){sessionStorage.setItem('welcomeDismissed','1');syncWelcome();document.querySelector('#baselineForm input')?.scrollIntoView({behavior:'smooth',block:'center'});}});
